// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        c = new SimpleSuicide(); // actor becomes the smartfix_owner
        amount = bound(amount, 0, address(this).balance + 1e30);
        vm.deal(address(this), amount);
        vm.deal(address(c), amount);
        vm.prank(actor);
        c.sudicideAnyone();
        assertTrue(address(c).balance == 0);
    }
}
